[data-bz-node="ba-grid"] { margin-top: var(--space-5); }
[data-bz-node^="ba-pair"] { position: relative; }
[data-bz-node^="ba-pair"] .bz-block { padding-block: 0 var(--space-2); }
[data-bz-node^="ba-after"] .bz-figure, [data-bz-node^="ba-before"] .bz-figure { position: relative; }
[data-bz-node^="ba-after"] .bz-figure::after, [data-bz-node^="ba-before"] .bz-figure::after { position: absolute; left: 12px; top: 12px; padding: 5px 11px; border-radius: var(--radius-chip); font: 700 12px/1 var(--font-body); background: rgb(12 19 34 / .72); color: #fff; }
[data-bz-node^="ba-after"] .bz-figure::after { content: 'After ⚡'; background: var(--volt); color: var(--ink); }
[data-bz-node^="ba-before"] .bz-figure::after { content: 'Before'; }
[data-bz-node^="ba-label"] p { font-weight: 700 !important; color: var(--ink) !important; font-size: 15px; }
/* Staged by the component script: one comparison stage, the pairs become pickers. */
.ba-stage { position: relative; aspect-ratio: 4 / 3; max-width: 980px; margin: var(--space-6) auto 0; border-radius: var(--radius-modal); overflow: hidden; box-shadow: var(--shadow-lift); background: var(--ink); --ba: 50%; }
.ba-stage img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; border-radius: 0; }
.ba-stage .ba-before { clip-path: inset(0 calc(100% - var(--ba)) 0 0); }
.ba-handle { position: absolute; top: 0; bottom: 0; left: var(--ba); width: 3px; margin-left: -1.5px; background: #fff; pointer-events: none; }
.ba-handle span { position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); width: 46px; height: 46px; border-radius: 50%; background: #fff; display: grid; place-items: center; font-weight: 800; color: var(--ink); box-shadow: 0 8px 24px rgb(0 0 0 / .3); }
.ba-tag { position: absolute; top: 16px; padding: 7px 13px; border-radius: var(--radius-chip); font: 700 13px/1 var(--font-body); pointer-events: none; }
.ba-tag--before { left: 16px; background: rgb(12 19 34 / .72); color: #fff; }
.ba-tag--after { right: 16px; background: var(--volt); color: var(--ink); }
.ba-range { position: absolute; inset: 0; width: 100%; height: 100%; opacity: 0; cursor: ew-resize; margin: 0; }
[data-bz-section="before-after"].is-staged [data-bz-node="ba-grid"] { max-width: 520px; margin-inline: auto; }
[data-bz-section="before-after"].is-staged [data-bz-node^="ba-before"], [data-bz-section="before-after"].is-staged [data-bz-node^="ba-label"] { display: none; }
[data-bz-section="before-after"].is-staged [data-bz-node^="ba-after"] .bz-figure::after { content: none; }
[data-bz-section="before-after"].is-staged [data-bz-node^="ba-pair"] { cursor: pointer; border-radius: 14px; outline: 3px solid transparent; outline-offset: 3px; opacity: .65; transition: opacity .2s ease, outline-color .2s ease; }
[data-bz-section="before-after"].is-staged [data-bz-node^="ba-pair"].is-active { outline-color: var(--accent); opacity: 1; }
@media (max-width: 640px) { [data-bz-section="before-after"].is-staged [data-bz-node="ba-grid"] > .bz-col { grid-column: span 4; } [data-bz-section="before-after"].is-staged [data-bz-node="ba-grid"] { grid-template-columns: repeat(12, 1fr); } }

