/* Before / after: build a drag-to-compare stage above the photo pairs.
   Without this script (and on the Design canvas) each pair simply shows the
   enhanced and original photos side by side, labelled. The stage is a real
   range input stretched over the photos, so mouse, touch and keyboard all work. */
(function () {
  document.querySelectorAll('[data-bz-section="before-after"]').forEach(function (root) {
    var pairs = Array.prototype.slice.call(root.querySelectorAll('[data-bz-node^="ba-pair"]'));
    var grid = root.querySelector('[data-bz-node="ba-grid"]');
    if (!pairs.length || !grid) return;
    var stage = document.createElement('div');
    stage.className = 'ba-stage';
    stage.innerHTML =
      '<img class="ba-after" alt="" /><img class="ba-before" alt="" />' +
      '<div class="ba-handle" aria-hidden="true"><span>\u27F7</span></div>' +
      '<span class="ba-tag ba-tag--before">Before</span><span class="ba-tag ba-tag--after">After \u26A1</span>' +
      '<input class="ba-range" type="range" min="0" max="100" value="50" aria-label="Drag to compare the original and enhanced photo" />';
    grid.parentNode.insertBefore(stage, grid);
    var after = stage.querySelector('.ba-after');
    var before = stage.querySelector('.ba-before');
    var range = stage.querySelector('.ba-range');
    range.addEventListener('input', function () { stage.style.setProperty('--ba', range.value + '%'); });
    function pick(i) {
      var imgs = pairs[i].querySelectorAll('img');
      if (imgs.length < 2) return;
      after.src = imgs[0].currentSrc || imgs[0].src; after.alt = imgs[0].alt;
      before.src = imgs[1].currentSrc || imgs[1].src; before.alt = imgs[1].alt;
      pairs.forEach(function (p, j) { p.classList.toggle('is-active', i === j); p.setAttribute('aria-pressed', String(i === j)); });
    }
    pairs.forEach(function (p, i) {
      p.setAttribute('role', 'button');
      p.setAttribute('tabindex', '0');
      p.setAttribute('aria-label', 'Show photo ' + (i + 1));
      p.addEventListener('click', function () { pick(i); });
      p.addEventListener('keydown', function (e) { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); pick(i); } });
    });
    pick(0);
    root.classList.add('is-staged');
  });
})();
